 static const char *chunkify_string(sinsp_span_t *sinsp_span, const char *key) {
     char *chunk_string = (char *) wmem_map_lookup(sinsp_span->str_chunk, key);
+#ifdef SS_MEMORY_STATISTICS
+    total_chunked_strings++;
+#endif

     if (!chunk_string) {
+#ifdef SS_MEMORY_STATISTICS
